/**
 * General query shapes over one data set: 200,000 events, each with one of 64 low-cardinality keys, one of 25,000
 * high-cardinality keys and four distinct values (1.2 million statements, indexes {@code spoc,posc}). Every shape reads
 * and hashes all projected values of every row and checks the row count.
 * <p>
 * This source file is kept identical on RDF4J 6.1.0 and on later branches so the scores can be compared directly.
 * Evaluation features that only exist on later branches are switched off through reflection.
 */
@State(Scope.Benchmark)
@Warmup(iterations = 4, time = 3)
@Measurement(iterations = 4, time = 3)
@BenchmarkMode(Mode.AverageTime)
@Fork(value = 1, jvmArgs = { "--enable-native-access=ALL-UNNAMED", "-Xms2G", "-Xmx2G", "-XX:+UseG1GC",
		"-XX:ActiveProcessorCount=4" })
@OutputTimeUnit(TimeUnit.MILLISECONDS)
public class QueryOverheadBenchmark {

	private static final int EVENTS = 200_000;
	private static final int VALUES_PER_EVENT = 4;
	private static final int LOW_GROUPS = 64;
	private static final int HIGH_GROUPS = 25_000;
	private static final int POINT_LOOKUPS = 10_000;

	private static final String LOW = "?event <urn:bench:low-key> ?key . ";
	private static final String HIGH = "?event <urn:bench:high-key> ?high . ";
	private static final String VALUE = "?event <urn:bench:value> ?v . ";

	/** The query shape to run. */
	@Param({ "scanValues", "scanKeys", "scanAll", "join2", "join3", "boundKeyJoin", "filterJoin", "optional",
			"countJoin", "groupCount", "distinctKeys", "pointLookups" })
	public String shape;

	private File dataDir;
	private SailRepository repository;
	private SailRepositoryConnection connection;
	private TupleQuery query;
	private long expectedRows;
	private IRI[] lookupEvents;

	public static void main(String[] args) throws RunnerException {
		Options opt = new OptionsBuilder()
				.include("QueryOverheadBenchmark\\.") // adapt to control which benchmarks to run
				.forks(1)
				.build();

		new Runner(opt).run();
	}

	@Setup(Level.Trial)
	public void setUp() throws Exception {
		dataDir = Files.createTempDirectory("lmdb-query-overhead").toFile();

		SailRepository loading = open(dataDir);
		try (SailRepositoryConnection loader = loading.getConnection()) {
			loader.begin();
			ValueFactory vf = loader.getValueFactory();
			IRI lowPredicate = vf.createIRI("urn:bench:low-key");
			IRI highPredicate = vf.createIRI("urn:bench:high-key");
			IRI valuePredicate = vf.createIRI("urn:bench:value");
			for (int i = 0; i < EVENTS; i++) {
				IRI event = vf.createIRI("urn:bench:event:" + i);
				loader.add(event, lowPredicate, vf.createIRI("urn:bench:low-group:" + (i % LOW_GROUPS)));
				loader.add(event, highPredicate, vf.createIRI("urn:bench:high-group:" + (i % HIGH_GROUPS)));
				int valueStart = i * VALUES_PER_EVENT;
				for (int j = 0; j < VALUES_PER_EVENT; j++) {
					loader.add(event, valuePredicate, vf.createLiteral(Integer.toString(valueStart + j)));
				}
			}
			loader.commit();
		} finally {
			loading.shutDown();
		}

		repository = open(dataDir);
		connection = repository.getConnection();
		long joinRows = (long) EVENTS * VALUES_PER_EVENT;
		String text;
		switch (shape) {
		case "scanValues":
			text = "SELECT ?event ?v WHERE { " + VALUE + "}";
			expectedRows = joinRows;
			break;
		case "scanKeys":
			text = "SELECT ?event ?key WHERE { " + LOW + "}";
			expectedRows = EVENTS;
			break;
		case "scanAll":
			text = "SELECT ?s ?p ?o WHERE { ?s ?p ?o }";
			expectedRows = (long) EVENTS * (VALUES_PER_EVENT + 2);
			break;
		case "join2":
			text = "SELECT ?key ?v WHERE { " + LOW + VALUE + "}";
			expectedRows = joinRows;
			break;
		case "join3":
			text = "SELECT ?key ?high ?v WHERE { " + LOW + HIGH + VALUE + "}";
			expectedRows = joinRows;
			break;
		case "boundKeyJoin":
			text = "SELECT ?event ?v WHERE { ?event <urn:bench:low-key> <urn:bench:low-group:7> . " + VALUE + "}";
			expectedRows = joinRows / LOW_GROUPS;
			break;
		case "filterJoin":
			text = "SELECT ?key ?v WHERE { " + LOW + VALUE + "FILTER(?key != <urn:bench:low-group:0>) }";
			expectedRows = joinRows - joinRows / LOW_GROUPS;
			break;
		case "optional":
			text = "SELECT ?event ?key ?high WHERE { " + LOW + "OPTIONAL { " + HIGH + "} }";
			expectedRows = EVENTS;
			break;
		case "countJoin":
			text = "SELECT (COUNT(*) AS ?count) WHERE { " + LOW + VALUE + "}";
			expectedRows = 1;
			break;
		case "groupCount":
			text = "SELECT ?key (COUNT(?v) AS ?count) WHERE { " + LOW + VALUE + "} GROUP BY ?key";
			expectedRows = LOW_GROUPS;
			break;
		case "distinctKeys":
			text = "SELECT DISTINCT ?key WHERE { " + LOW + "}";
			expectedRows = LOW_GROUPS;
			break;
		case "pointLookups":
			text = "SELECT ?v WHERE { " + VALUE + "}";
			expectedRows = (long) POINT_LOOKUPS * VALUES_PER_EVENT;
			lookupEvents = new IRI[POINT_LOOKUPS];
			for (int i = 0; i < POINT_LOOKUPS; i++) {
				lookupEvents[i] = connection.getValueFactory()
						.createIRI("urn:bench:event:" + (i * (EVENTS / POINT_LOOKUPS)));
			}
			break;
		default:
			throw new IllegalArgumentException("Unknown query shape " + shape);
		}
		query = connection.prepareTupleQuery(text);
	}

	@TearDown(Level.Trial)
	public void tearDown() {
		try {
			if (connection != null) {
				connection.close();
			}
		} finally {
			try {
				if (repository != null) {
					repository.shutDown();
				}
			} finally {
				LmdbTestUtil.deleteDir(dataDir);
			}
		}
	}

	/** Evaluates the selected shape and reads every projected value of every row. */
	@Benchmark
	public long run() {
		long rows = 0;
		long checksum = 1;
		if (lookupEvents == null) {
			try (TupleQueryResult result = query.evaluate()) {
				String[] names = result.getBindingNames().toArray(new String[0]);
				while (result.hasNext()) {
					checksum += hash(result.next(), names);
					rows++;
				}
			}
		} else {
			for (IRI event : lookupEvents) {
				query.setBinding("event", event);
				try (TupleQueryResult result = query.evaluate()) {
					while (result.hasNext()) {
						checksum += result.next().getValue("v").hashCode();
						rows++;
					}
				}
			}
		}
		if (rows != expectedRows) {
			throw new IllegalStateException("Shape " + shape + " returned " + rows + " rows, expected " + expectedRows);
		}
		return checksum;
	}

	private static long hash(BindingSet bindings, String[] names) {
		long hash = 0;
		for (String name : names) {
			Value value = bindings.getValue(name);
			hash = hash * 31 + (value == null ? 0 : value.hashCode());
		}
		return hash;
	}

	private static SailRepository open(File dataDir) throws ReflectiveOperationException {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc");
		setIfPresent(config, "setNativeEvaluationEnabled", false);
		setIfPresent(config, "setDirectAdjacencyEnabled", false);
		setIfPresent(config, "setDirectAdjacencyMode", "DISABLED");
		config.setOptimizerSamplingEnabled(false);
		// -Dbench.autoGrow=false runs with fixed map sizes; the maps are sized for the data set either way.
		if (!Boolean.parseBoolean(System.getProperty("bench.autoGrow", "true"))) {
			config.setAutoGrow(false);
			config.setTripleDBSize(2L * 1024 * 1024 * 1024);
			config.setValueDBSize(2L * 1024 * 1024 * 1024);
		}
		LmdbStore store = new LmdbStore(dataDir, config);
		setIfPresent(store, "setExperimentalQueryOptimizations", false);
		SailRepository repository = new SailRepository(store);
		repository.init();
		return repository;
	}

	/** Applies a setting that only later branches have; a release without the setter is left as it is. */
	@SuppressWarnings({ "unchecked", "rawtypes" })
	private static void setIfPresent(Object target, String setter, Object value) throws ReflectiveOperationException {
		for (Method method : target.getClass().getMethods()) {
			if (method.getName().equals(setter) && method.getParameterCount() == 1) {
				Class<?> type = method.getParameterTypes()[0];
				method.invoke(target, type.isEnum() ? Enum.valueOf((Class) type, (String) value) : value);
				return;
			}
		}
	}
}
